 * Epoch-ms of the wall clock in `timeZone` at `instant`, read as if it were
 * UTC. Subtracting `instant` gives the zone's offset at that moment.
 */
function wallClockMs(instant: number, timeZone: string): number {
  const parts: Record<string, number> = {};
  for (const part of zoneFormatter(timeZone).formatToParts(instant)) {
    if (part.type !== "literal") parts[part.type] = Number(part.value);
  }
  return Date.UTC(
    parts.year,
    parts.month - 1,
    parts.day,
    parts.hour,
    parts.minute,
    parts.second,
  );
}

const formatters = new Map<string, Intl.DateTimeFormat>();

/** Throws a `RangeError` for a zone name `Intl` does not recognise. */
function zoneFormatter(timeZone: string): Intl.DateTimeFormat {
  const cached = formatters.get(timeZone);
  if (cached) return cached;

  const formatter = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
  formatters.set(timeZone, formatter);
  return formatter;
}

/** True when `Intl` knows the IANA zone name, e.g. "Asia/Tokyo". */
export function isValidTimeZone(timeZone: string): boolean {
  try {
    zoneFormatter(timeZone);
    return true;
  } catch {
    return false;
  }
}

/** Throws a `RangeError` naming the zone when `Intl` does not know it. */
export function assertTimeZone(timeZone: string): void {
  if (!isValidTimeZone(timeZone)) {
    throw new RangeError(`Unknown time zone: "${timeZone}"`);
  }
}

/**
 * The instant whose wall clock in `timeZone` reads `wallMs`. Two passes of
 * the offset correction settle on the right side of a DST transition for
 * every zone that does not skip exactly the wall time asked for.
 */
function instantForWallClock(wallMs: number, timeZone: string): number {
  let instant = wallMs;
  for (let pass = 0; pass < 2; pass += 1) {
    instant = wallMs - (wallClockMs(instant, timeZone) - instant);
  }
  return instant;
}

/** `YYYY-MM-DD` of the zone's calendar day that contains `instant`. */
function calendarDateOf(instant: number, timeZone: string): string {
  return new Date(wallClockMs(instant, timeZone)).toISOString().slice(0, 10);
}

/** `date` (`YYYY-MM-DD`) moved by `days` calendar days; zone-free arithmetic. */
export function addCalendarDays(date: string, days: number): string {
