    .toISOString()
    .slice(0, 10);
}

/** The `YYYY-MM-DD` calendar date of `value` on the clock of `timeZone`. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  return calendarDateOf(parseIso(value).getTime(), timeZone);
